// === Tab: tab2.js ===
class Particle{
  constructor(x,y,life,usure){
    this.pos = createVector(x, y);
    this.vel = createVector(0, 0);
this.life = life;
		this.usure=usure;

		// Set the line thickness (stroke weight) here
    this.strokeWeight = 2; // Adjust this value to control thickness
		this.colour = colours[(round(random(colours.length-1)))];
  }
	show(){
		strokeWeight(this.strokeWeight);
		stroke(this.colour);
		if(this.life>0)line(this.pos.x, this.pos.y, this.pos.x - this.vel.x, this.pos.y - this.vel.y);
	//line(this.pos.x, this.pos.y, this.pos.x - this.vel.x, this.pos.y - this.vel.y);
	}
 update(){
	 this.life-=this.usure;
    this.vel = createVector(0, 0);
    for(let i = 0; i < attractors.length; i++){
      this.vector = p5.Vector.sub(this.pos, attractors[i].pos);
      this.vector.setMag(1/this.vector.mag());
      if(attractors[i].clockwise) this.vector.rotate(-1.5);
      else this.vector.rotate(1.5);
      this.vel.add(this.vector);
    }
    this.vel.setMag(8);
    this.pos.add(this.vel);
	 	/*
		if(this.pos.x > width || this.pos.x < 0 || this.pos.y > height || this.pos.y < 0){
			this.pos = createVector(random(width), random(height));
		}
		*/
	}
}

// === Tab: tab3.js ===

class Attractor{
	constructor(){
		this.pos = createVector(random(width), random(height));
		this.vel = createVector(random(-0.5, 0.5), random(-5, 5));
		if(random(1) > 0.5) this.clockwise = true;
    else this.clockwise = false;
	}
	show(){
    if(this.clockwise) fill(255, 0, 0);
    else fill(0, 255, 0);
    circle(this.pos.x, this.pos.y, 50);
  }
	update(){

		//this.vel = createVector(random(width), random(height));

		this.pos.add(this.vel);

		if(this.pos.x >= width || this.pos.x <= 0) this.vel.x *=  -1;
		if(this.pos.y >= height || this.pos.y <= 0) this.vel.y *=  -1;
	}
}

